Android中对话框的展示，对人机交互有着重要的意义，常见的对话框包括：

警告对话框
进度对话框
日期选择对话框
时间选择对话框
普通列表对话框
单选列表对话框
多选列表对话框
带图标的列表对话框

对于特殊的对话框形式还可以自定义对话框
下面对这些对话框的使用进行说明：
警告对话框private void showAlertDialog() &#123;        AlertDialog.Builder builder = new AlertDialog.Builder(this);        builder.setTitle(&quot;提示&quot;);        builder.setIcon(R.mipmap.ic_launcher);        builder.setMessage(&quot;您有一笔2千万的汇款在处理，请问是您亲自操作的吗？&quot;);        builder.setPositiveButton(R.string.confirm, new DialogInterface.OnClickListener() &#123;            @Override            public void onClick(DialogInterface dialogInterface, int i) &#123;                Log.d(TAG, &quot;onClick: &quot; + i);                toast(R.string.confirm);            &#125;        &#125;);        builder.setNegativeButton(R.string.cancel, new DialogInterface.OnClickListener() &#123;            @Override            public void onClick(DialogInterface dialogInterface, int i) &#123;                dialogInterface.dismiss();                toast(R.string.cancel);            &#125;        &#125;);        builder.setNeutralButton(R.string.exit, new DialogInterface.OnClickListener() &#123;            @Override            public void onClick(DialogInterface dialogInterface, int i) &#123;                Log.d(TAG, &quot;onClick: &quot; + i);                toast(R.string.exit);            &#125;        &#125;);        AlertDialog dialog = builder.create();        dialog.show();&#125;

进度对话框private void showPgsDialog() &#123;        final ProgressDialog dialog = new ProgressDialog(this);        dialog.setTitle(&quot;下载提示&quot;);        dialog.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);        dialog.setMax(100);        dialog.setButton(DialogInterface.BUTTON_POSITIVE, getString(R.string.background), new DialogInterface.OnClickListener() &#123;            @Override            public void onClick(DialogInterface dialog, int which) &#123;            &#125;        &#125;);        dialog.onStart();        new Thread(new Runnable() &#123;            @Override            public void run() &#123;                int i = 10;                while (i &lt;= 100) &#123;                    try &#123;                        Thread.sleep(100);                        dialog.incrementProgressBy(1);                        i++;                    &#125; catch (InterruptedException e) &#123;                        e.printStackTrace();                    &#125;                &#125;                dialog.dismiss();            &#125;        &#125;).start();        dialog.show();&#125;

日期选择对话框private void showDatePickerDialog() &#123;        Calendar calendar = Calendar.getInstance();        int year = calendar.get(Calendar.YEAR);        int month = calendar.get(Calendar.MONTH);        int day = calendar.get(Calendar.DAY_OF_MONTH);        DatePickerDialog dialog = new MyDatePickerDialog(this, new DatePickerDialog.OnDateSetListener() &#123;            @Override            public void onDateSet(DatePicker datePicker, int year, int monthOfYear, int dayOfMonth) &#123;                Log.d(TAG, &quot;onDateSet: &quot; + year + &quot;.&quot; + (monthOfYear + 1) + &quot;.&quot; + dayOfMonth);                toast(&quot;你选择的日期是：&quot; + year + &quot;.&quot; + (monthOfYear + 1) + &quot;.&quot; + dayOfMonth);            &#125;        &#125;, year, month, day);        dialog.show();&#125;
在构造DatePickerDialog的时候需要传入初始化的year,month,day，monthOfYear是从0开始的，所以得到的月份要记得加1。
时间选择对话框private void showTimePickerDialog() &#123;        Calendar calendar = Calendar.getInstance();        int hour = calendar.get(Calendar.HOUR_OF_DAY);        int minute = calendar.get(Calendar.MINUTE);        TimePickerDialog dialog = new MyTimePickerDialog(this, new TimePickerDialog.OnTimeSetListener() &#123;            @Override            public void onTimeSet(TimePicker timePicker, int hourOfDay, int minute) &#123;                Log.d(TAG, &quot;onTimeSet: &quot; + hourOfDay + &quot;:&quot; + minute);                toast(&quot;你选择的时间是：&quot; + hourOfDay + &quot;:&quot; + minute);            &#125;        &#125;, hour, minute, true);        dialog.show();&#125;
在构造TimePickerDialog时要传入初始化的hour和minute，第五个参数是布尔型变量，是否是24小时制，传入true设置24小时制，反之亦然。
注意：在使用DatePickerDialog和TimePickerDialog时，要解决兼容性的问题，在回调onDateSet时，4.3系统后会回调两次，而4.3以下的则回调一次，这样很影响业务逻辑，要解决这个问题，需要重写DatePickerDialog的onStop方法，将super.onStop()方法去掉即可。详细可参考http://blog.csdn.net/wxuande/article/details/44002791
public class MyDatePickerDialog extends DatePickerDialog &#123;    public MyDatePickerDialog(Context context, OnDateSetListener listener, int year, int month, int dayOfMonth) &#123;        super(context, listener, year, month, dayOfMonth);    &#125;    public MyDatePickerDialog(Context context, int themeResId, OnDateSetListener listener, int year, int monthOfYear, int dayOfMonth) &#123;        super(context, themeResId, listener, year, monthOfYear, dayOfMonth);    &#125;    //解决兼容性问题，即onDateSet方法回调两次的bug    @Override    protected void onStop() &#123;    &#125;&#125;

普通列表对话框//核心方法builder.setItems(arrayColor, new DialogInterface.OnClickListener() &#123;    @Override    public void onClick(DialogInterface dialogInterface, int i) &#123;        Log.d(TAG, &quot;onClick: &quot; + arrayColor[i]);        toast(&quot;你选择的是：&quot; + arrayColor[i]);    &#125;&#125;);

单选列表对话框//核心方法builder.setSingleChoiceItems(arrayGender, -1, new DialogInterface.OnClickListener() &#123;    @Override    public void onClick(final DialogInterface dialogInterface, int i) &#123;        Log.d(TAG, &quot;onClick: &quot; + arrayGender[i]);        toast(&quot;你选择的是：&quot; + arrayGender[i]);    &#125;&#125;);
setSingleChoiceItems的第二个参数是item的index，-1表示不预先选择，0表示选择第一项，以此类推。
多选列表对话框final boolean[] pos = new boolean[arrayFruits.length];builder.setMultiChoiceItems(arrayFruits, null, new DialogInterface.OnMultiChoiceClickListener() &#123;    @Override    public void onClick(DialogInterface dialogInterface, int i, boolean b) &#123;        pos[i] = b;    &#125;&#125;);builder.setPositiveButton(R.string.confirm, new DialogInterface.OnClickListener() &#123;    @Override    public void onClick(DialogInterface dialogInterface, int which) &#123;        StringBuilder sb = new StringBuilder();        for (int i = 0, length = pos.length; i &lt; length; i++) &#123;            if (pos[i]) &#123;                sb.append(arrayFruits[i]);                sb.append(&quot;、&quot;);            &#125;        &#125;        Log.d(TAG, &quot;onClick: &quot; + sb.deleteCharAt(sb.length() - 1).toString());        toast(&quot;你选择的是：&quot; + sb.deleteCharAt(sb.length() - 1).toString());    &#125;&#125;);
setMultiChoiceItems的第二个参数表示的是被选中的item，null表示不设默认值。
带图标的列表对话框builder.setAdapter(new ListItemAdapter(), new DialogInterface.OnClickListener() &#123;    @Override    public void onClick(DialogInterface dialog, int which) &#123;        toast(&quot;你选择的是：&quot; + arrayColor[which]);    &#125;&#125;);private class ListItemAdapter extends BaseAdapter &#123;    int[] imgIds = &#123;R.mipmap.ic_launcher, R.mipmap.ic_launcher, R.mipmap.ic_launcher&#125;;    @Override    public int getCount() &#123;        return imgIds.length;    &#125;    @Override    public Integer getItem(int position) &#123;        return imgIds[position];    &#125;    @Override    public long getItemId(int position) &#123;        return position;    &#125;    @Override    public View getView(int position, View convertView, ViewGroup parent) &#123;        TextView textView = new TextView(MainActivity.this);        textView.setText(getResources().getStringArray(R.array.colors)[position]);        textView.setTextSize(24);        AbsListView.LayoutParams layoutParams = new AbsListView.LayoutParams(                AbsListView.LayoutParams.MATCH_PARENT, AbsListView.LayoutParams.WRAP_CONTENT        );        textView.setGravity(Gravity.CENTER_VERTICAL);        textView.setLayoutParams(layoutParams);        textView.setCompoundDrawablesWithIntrinsicBounds(getItem(position), 0, 0, 0);        textView.setPadding(40, 0, 40, 0);        textView.setCompoundDrawablePadding(8);        return textView;    &#125;&#125;

自定义对话框final View root = LayoutInflater.from(this).inflate(R.layout.dialog_login, null);builder.setView(root);builder.setPositiveButton(R.string.confirm, new DialogInterface.OnClickListener() &#123;    @Override    public void onClick(DialogInterface dialog, int which) &#123;        String name = ((EditText) root.findViewById(R.id.et_name)).getText().toString();        String pwd = ((EditText) root.findViewById(R.id.et_pwd)).getText().toString();        if (TextUtils.isEmpty(name)) &#123;            toast(&quot;账号不能为空&quot;);            return;        &#125;        if (TextUtils.isEmpty(pwd)) &#123;            toast(&quot;密码不能为空&quot;);            return;        &#125;        toast(&quot;账号：&quot; + name + &quot;, 密码：&quot; + pwd);    &#125;&#125;);
这里是创建一个布局文件，当然也可以直接定义控件，但是要注意布局的美观就可以了。

前言对于普通的编辑框，它的功能就是负责接收用户输入的信息，在实际开发中，常常会有这样的设计，就是在输入内容后，编辑框的内部右侧会出现一个删除按钮，点击后会清空编辑框里的内容，这样的交互是极好的，那这又是怎么实现的呢？
解决思路毫无疑问是——继承自EditText，自定义文本编辑框
为EditText设置addTextChangeListener

创建内部类实现TextWatcher接口，监听输入框文本的变化
改写onTouchEvent事件，点击叉号位置，清空文本
通过setCompoundDrawablesWithIntrinsicBounds方法为EditText设置图片
提示，先准备一张png的图片，由于EditText是继承自TextView的，因此也有setCompoundDrawablesWithIntrinsicBounds方法。

自定义EditTextWithDel类继承自EditText，重写构造函数。
public EditTextWithDel(Context context) &#123;    super(context);    mContext = context;    init();&#125;public EditTextWithDel(Context context, AttributeSet attrs) &#123;    super(context, attrs);    mContext = context;    init();&#125;public EditTextWithDel(Context context, AttributeSet attrs, int defStyleAttr) &#123;    super(context, attrs, defStyleAttr);    mContext = context;    init();&#125;

监听文本是否改变的事件private void init() &#123;        imgInable = mContext.getResources().getDrawable(R.drawable.delete_grey);        addTextChangedListener(new EditTextWatcher());        setDrawable();&#125;

创建内部类实现TextWatcher接口private class EditTextWatcher implements TextWatcher &#123;        @Override        public void beforeTextChanged(CharSequence s, int start, int count, int after) &#123;            //文本将要被替换        &#125;        @Override        public void onTextChanged(CharSequence s, int start, int before, int count) &#123;            //旧文本正在被替换        &#125;        @Override        public void afterTextChanged(Editable s) &#123;            //文本已经被替换            setDrawable();        &#125;&#125;

重写onTouchEvent事件@Overridepublic boolean onTouchEvent(MotionEvent event) &#123;        if (imgInable != null &amp;&amp; event.getAction() == MotionEvent.ACTION_UP) &#123;            int eventX = (int) event.getRawX();            int eventY = (int) event.getRawY();            Log.e(TAG, &quot;eventX = &quot; + eventX + &quot;; eventY = &quot; + eventY);            Rect rect = new Rect();            getGlobalVisibleRect(rect);//获取视图在屏幕坐标中的可视区域            rect.left = rect.right - 100;            if (rect.contains(eventX, eventY)) &#123;                setText(&quot;&quot;);//判断是否在叉号范围内，在就清空            &#125;        &#125;        return super.onTouchEvent(event);&#125;

设置叉号视图private void setDrawable() &#123;        if (length() &lt; 1) &#123;            setCompoundDrawablesWithIntrinsicBounds(null, null, null, null);        &#125; else &#123;            //左、上、右、下，这样的参数都是套路，记下就行            setCompoundDrawablesWithIntrinsicBounds(null, null, imgInable, null);        &#125;&#125;
其实也很简单，就是判断文本框内容的长度，长度超过1的就设置叉号视图，小于1的就设置为null。


